// AUSTRALIA — Atlas reference destination. Original content written for Fluent30.
// English is the national language in practice; Australia is also home to many Aboriginal and
// Torres Strait Islander peoples and languages. Accent for listening: en-AU (device voices).
import type { DialogueLine } from "../../curriculum/types";
import type { AtlasDestination, AtlasExercise, Band, Mechanic } from "../types";

// ---------- builders ----------
const L: Band[] = ["A1", "A2", "B1"];
const M: Band[] = ["A2", "B1", "B2"];
const H: Band[] = ["B1", "B2", "C1"];
const ALL: Band[] = ["A1", "A2", "B1", "B2", "C1"];

const mcq = (bands: Band[], prompt: string, options: string[], answer: number, explain: string, fr?: string): AtlasExercise => ({ type: "mcq", prompt, options, answer, explain, fr, bands });
const fill = (bands: Band[], sentence: string, answers: string[], explain: string, fr?: string, hint?: string): AtlasExercise => ({ type: "fill", sentence, answers, explain, fr, hint, bands });
const tr = (bands: Band[], from: "fr" | "en", text: string, answers: string[], explain: string): AtlasExercise => ({ type: "translate", from, text, answers, explain, bands });
const reo = (bands: Band[], answer: string, explain: string, fr?: string): AtlasExercise => ({ type: "reorder", words: answer.split(" "), answer, explain, fr, bands });
const fix = (bands: Band[], sentence: string, answers: string[], explain: string): AtlasExercise => ({ type: "fix", sentence, answers, explain, bands });
const lis = (bands: Band[], audio: string, question: string, options: string[], answer: number, explain: string): AtlasExercise => ({ type: "listen", audio, question, options, answer, explain, bands });
const dic = (bands: Band[], audio: string, answers: string[], explain: string): AtlasExercise => ({ type: "dictation", audio, answers, explain, bands });
const mat = (bands: Band[], pairs: [string, string][], explain?: string): AtlasExercise => ({ type: "match", pairs, explain, bands });
const say = (speaker: string, en: string, fr?: string): DialogueLine => ({ speaker, en, fr });
const you = (fr: string, ...choices: [string, boolean, string][]): DialogueLine => {
  const list = choices.map(([en, correct, why]) => ({ en, correct, why }));
  const r = [...fr].reduce((a, c) => a + c.charCodeAt(0), 0) % list.length;
  return { speaker: "You", fr, choices: [...list.slice(r), ...list.slice(0, r)] };
};
const dlg = (bands: Band[], intro: string, ...lines: DialogueLine[]): AtlasExercise => ({ type: "dialogue", intro, lines, bands });
const mech = (bands: Band[], m: Mechanic): AtlasExercise => ({ ...m, bands });
const produce = (title: string, prompt: string, fr: string, mustInclude: string[][], minWords: number, samples: string[], tip: string): Extract<Mechanic, { type: "produce" }> => ({ type: "produce", title, prompt, fr, mustInclude, minWords, samples, tip });

